-- 역삼역(station_id=1) 전체구간 경로 그래프 재시드 (S15P11A206-312)
-- B2·B3 일부 구간(노드 18·간선 11) -> B1·B2·B3 전체 구간(노드 142·간선 205)으로 교체한다.
-- 원본: 역삼역_11_30.json (version 17). 이 파일은 그 JSON에서 생성했다.
--
-- V4·V5 는 수정하지 않는다. 이미 적용된 DB의 Flyway 체크섬이 깨지기 때문이다.
-- 대신 이 마이그레이션이 station_id=1 의 그래프를 비우고 새로 채운다.
--
-- 좌표계: 캐노니컬 미터 프레임. 원점 = B2-B3 층간 엘리베이터 B, +X = 6번출구 방향(이미지 기준 -21.28deg),
--         0.19 m/px(provisional), z(B1=5 / B2=0 / B3=-5).
--         B1 개찰구 위쪽 중간층(B0.5)은 별도 층이 아니라 floor_code=B1 안의 map_z=7.5 로 둔다.
-- 거리  : 3D 유클리드(x, y, z). 같은 층 안에도 B0.5 때문에 높이차가 있다.
-- 상세  : docs/역삼역_route_node_naming.md

-- 0) 역삼역 station 보장 (fresh DB·CI 에서 FK 실패 방지)
INSERT INTO station (station_id, name_ko, name_en, line_info, latitude, longitude, is_active, created_at, updated_at)
SELECT 1, '역삼역', 'Yeoksam Station', '2호선', 37.5007000, 127.0365000, 1, NOW(6), NOW(6)
WHERE NOT EXISTS (SELECT 1 FROM station WHERE station_id = 1);

-- 1) 층. B2·B3 는 V4 에서 생성됐고 B1 이 없다. 재적용 대비로 조건부 삽입한다.
INSERT INTO station_floor (station_id, floor_code, floor_name, floor_order, created_at, updated_at)
SELECT 1, 'B1', '지하 1층', 1, NOW(6), NOW(6)
WHERE NOT EXISTS (SELECT 1 FROM station_floor WHERE station_id = 1 AND floor_code = 'B1');
INSERT INTO station_floor (station_id, floor_code, floor_name, floor_order, created_at, updated_at)
SELECT 1, 'B2', '지하 2층', 2, NOW(6), NOW(6)
WHERE NOT EXISTS (SELECT 1 FROM station_floor WHERE station_id = 1 AND floor_code = 'B2');
INSERT INTO station_floor (station_id, floor_code, floor_name, floor_order, created_at, updated_at)
SELECT 1, 'B3', '지하 3층', 3, NOW(6), NOW(6)
WHERE NOT EXISTS (SELECT 1 FROM station_floor WHERE station_id = 1 AND floor_code = 'B3');

-- 2) 층 id 해석 (floor_id 는 DB 인스턴스마다 다르므로 코드로 조회한다)
SET @b1 := (SELECT floor_id FROM station_floor WHERE station_id = 1 AND floor_code = 'B1');
SET @b2 := (SELECT floor_id FROM station_floor WHERE station_id = 1 AND floor_code = 'B2');
SET @b3 := (SELECT floor_id FROM station_floor WHERE station_id = 1 AND floor_code = 'B3');

-- 3) 기존 그래프를 참조하는 행 정리
--    현재 개발 DB에서는 전부 0행이지만, 세션이 살아 있는 DB에서도 안전하게 돌아야 한다.
--    세션·위치공유·인식로그는 만료되는 임시 데이터라 정리해도 무해하다.
UPDATE user_session          SET current_node_id = NULL WHERE current_node_id IN (SELECT node_id FROM route_node WHERE station_id = 1);
UPDATE consultation_session  SET current_node_id = NULL WHERE current_node_id IN (SELECT node_id FROM route_node WHERE station_id = 1);
UPDATE vps_reference_image   SET node_id         = NULL WHERE node_id         IN (SELECT node_id FROM route_node WHERE station_id = 1);
UPDATE localization_log      SET matched_node_id = NULL WHERE matched_node_id IN (SELECT node_id FROM route_node WHERE station_id = 1);
-- shared_node_id 는 NOT NULL 이라 행 자체를 지운다.
DELETE FROM location_share WHERE shared_node_id IN (SELECT node_id FROM route_node WHERE station_id = 1);
-- facility 를 참조하는 두 테이블도 NOT NULL 이다.
DELETE FROM exit_detail               WHERE facility_id      IN (SELECT facility_id FROM facility WHERE station_id = 1);
DELETE FROM place_exit_recommendation WHERE exit_facility_id IN (SELECT facility_id FROM facility WHERE station_id = 1);

-- 4) 기존 그래프 삭제 (FK 역순: 간선 -> 시설 -> 노드)
DELETE FROM route_edge WHERE station_id = 1;
DELETE FROM facility   WHERE station_id = 1;
DELETE FROM route_node WHERE station_id = 1;

